diff --git a/src/feature.ts b/src/feature.ts
new file mode 100644
index 0000000..e7996e4
--- /dev/null
+++ b/src/feature.ts
@@ -0,0 +1,11 @@
+// Feature flags — in-memory registry, single process. Unknown flags are off.
+// Null prototype: arbitrary flag names can never collide with Object.prototype keys.
+const flags: Record<string, boolean> = Object.create(null);
+
+export function setFlag(flag: string, enabled: boolean): void {
+  flags[flag] = enabled;
+}
+
+export function isEnabled(flag: string): boolean {
+  return flags[flag] ?? false;
+}
